import React from "react";
import { Pages } from "@ai-matrx/applets/react";

export default function App() {
  return <Pages layout="tabs" />;
}

import React, { useState } from "react";
import { useRows } from "@ai-matrx/applets/react";
import { Button, Badge, Select, SearchField, EmptyState, RegionSkeleton } from "@ai-matrx/design-system/controls";
import { Plus, Pencil, Trash2, Check, X } from "lucide-react";

const SORTS = {
  title_asc: { column: "title", direction: "asc" },
  year_desc: { column: "year", direction: "desc" },
  year_asc: { column: "year", direction: "asc" },
};

const inputClass = "w-full rounded-md border border-border bg-card px-3 py-2 text-sm text-foreground";

export default function MoviesPage() {
  const [sortBy, setSortBy] = useState("title_asc");
  const [search, setSearch] = useState("");
  const [title, setTitle] = useState("");
  const [year, setYear] = useState("");
  const [formError, setFormError] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editTitle, setEditTitle] = useState("");
  const [editYear, setEditYear] = useState("");
  const [editError, setEditError] = useState("");

  const movies = useRows("movies", { sort: [SORTS[sortBy]], pageSize: 200 });

  const q = search.trim().toLowerCase();
  const visible = movies.rows.filter((row) => {
    if (!q) return true;
    const t = String(row.title || "").toLowerCase();
    const y = row.year == null ? "" : String(row.year);
    return t.includes(q) || y.includes(q);
  });

  const parseYear = (value) => {
    const n = Number(String(value).trim());
    if (!Number.isInteger(n) || n < 1880 || n > 2100) return null;
    return n;
  };

  const addMovie = async (e) => {
    e.preventDefault();
    setFormError("");
    const t = title.trim();
    if (!t) { setFormError("Title is required"); return; }
    const y = parseYear(year);
    if (y === null) { setFormError("Year must be a four-digit year"); return; }
    const answer = await movies.create({ title: t, year: y });
    if (!answer.ok) { setFormError(answer.error.message); return; }
    setTitle("");
    setYear("");
  };

  const startEdit = (row) => {
    setEditingId(row._id);
    setEditTitle(row.title || "");
    setEditYear(row.year == null ? "" : String(row.year));
    setEditError("");
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditError("");
  };

  const saveEdit = async (row) => {
    setEditError("");
    const t = editTitle.trim();
    if (!t) { setEditError("Title is required"); return; }
    const y = parseYear(editYear);
    if (y === null) { setEditError("Year must be a four-digit year"); return; }
    const answer = await movies.update(row._id, { title: t, year: y });
    if (!answer.ok) { setEditError(answer.error.message); return; }
    setEditingId(null);
  };

  const removeMovie = async (row) => {
    const answer = await movies.archive(row._id);
    if (!answer.ok) setFormError(answer.error.message);
  };

  return (
    <div className="mx-auto max-w-3xl space-y-6 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-xl font-semibold text-foreground">Favourite movies</h1>
        <Badge tone="neutral">{movies.rows.length} movies</Badge>
      </div>

      <form onSubmit={addMovie} className="rounded-lg border border-border bg-card p-4">
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-[1fr_8rem_auto]">
          <input
            className={inputClass}
            placeholder="Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            className={inputClass}
            placeholder="Year"
            inputMode="numeric"
            value={year}
            onChange={(e) => setYear(e.target.value)}
          />
          <Button variant="primary" type="submit">
            <Plus className="mr-1 h-4 w-4" />Add
          </Button>
        </div>
        {formError ? <p className="mt-2 text-sm text-destructive">{formError}</p> : null}
      </form>

      <div className="grid grid-cols-1 gap-3 sm:grid-cols-[1fr_12rem]">
        <SearchField
          placeholder="Search title or year"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Select
          value={sortBy}
          onValueChange={setSortBy}
          options={[
            { value: "title_asc", label: "Title A to Z" },
            { value: "year_desc", label: "Newest first" },
            { value: "year_asc", label: "Oldest first" },
          ]}
        />
      </div>

      {movies.status === "loading" ? (
        <RegionSkeleton shape="rows" count={5} />
      ) : movies.status === "error" ? (
        <p className="text-sm text-destructive">{movies.error && movies.error.message ? movies.error.message : "Could not load movies"}</p>
      ) : visible.length === 0 ? (
        <EmptyState title={q ? "No matches" : "No movies yet"} line={q ? "Try another search" : "Add your first favourite above"} />
      ) : (
        <ul className="divide-y divide-border rounded-lg border border-border bg-card">
          {visible.map((row) => (
            <li key={row._id} className="p-3">
              {editingId === row._id ? (
                <div className="space-y-2">
                  <div className="grid grid-cols-1 gap-2 sm:grid-cols-[1fr_8rem_auto_auto]">
                    <input
                      className={inputClass}
                      value={editTitle}
                      onChange={(e) => setEditTitle(e.target.value)}
                    />
                    <input
                      className={inputClass}
                      inputMode="numeric"
                      value={editYear}
                      onChange={(e) => setEditYear(e.target.value)}
                    />
                    <Button variant="primary" onClick={() => saveEdit(row)}>
                      <Check className="h-4 w-4" />
                    </Button>
                    <Button variant="quiet" onClick={cancelEdit}>
                      <X className="h-4 w-4" />
                    </Button>
                  </div>
                  {editError ? <p className="text-sm text-destructive">{editError}</p> : null}
                </div>
              ) : (
                <div className="flex items-center justify-between gap-3">
                  <div className="min-w-0">
                    <div className="truncate font-medium text-foreground">{row.title}</div>
                    <div className="text-sm text-muted-foreground">{row.year == null ? "Year unknown" : row.year}</div>
                  </div>
                  <div className="flex shrink-0 gap-1">
                    <Button variant="quiet" onClick={() => startEdit(row)}>
                      <Pencil className="h-4 w-4" />
                    </Button>
                    <Button variant="danger" onClick={() => removeMovie(row)}>
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              )}
            </li>
          ))}
        </ul>
      )}

      {movies.hasMore ? (
        <div className="flex justify-center">
          <Button variant="outline" onClick={() => movies.loadMore()}>Load more</Button>
        </div>
      ) : null}
    </div>
  );
}

